fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars = txt.chars();
    // Get the last character
    let last_char = match chars.next_back() {
        Some(c) => c,
        None => return false, // empty string
    };

    // Check if last_char is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // If only one character, return true
    if txt.chars().count() == 1 {
        return true;
    }

    // Otherwise check if the character before last is a space
    // We can use chars again from the front, get all but last character
    // and get the last of that slice.
    let mut chars_but_last = txt.chars();
    // discard last char
    chars_but_last.next_back();

    match chars_but_last.next_back() {
        Some(c) if c == ' ' => true,
        _ => false,
    }
}